mapper.select:
SELECT r.review_id, CASE WHEN r.is_hidden = 1 THEN '신고 누적으로 블라인드 처리된 리뷰입니다.' ELSE r.content END as content, r.rating, r.like_count, r.is_spoiler, r.is_hidden, r.created_at, u.user_id, u.nickname, u.profile_image_path as profileImagePath FROM reviews r JOIN users u ON r.user_id = u.user_id WHERE r.animation_id = #{animationId} AND r.deleted_at IS NULL
ORDER BY
r.rating r.like_count r.created_at r.created_at
${order.direction}
ORDER BY r.created_at DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}
